const raw = $input.first().json;
const body = (raw.body && typeof raw.body === 'object') ? raw.body
           : (typeof raw.body === 'string') ? JSON.parse(raw.body.replace(/^=+/, '').trim()) : raw;

const task_id     = String(body.task_id || 'unknown');
const userRequest = String(body.userRequest || '');
const language    = String(body.language || 'javascript');
const framework   = String(body.framework || 'express');
const lines       = userRequest.split('\n');

// ── 1. project_name ──────────────────────────────────────────────
let projectName = 'Application';
const titleMatch = userRequest.match(/^#\s+(.+)/m);
if (titleMatch) { projectName = titleMatch[1].trim().split(' ').slice(0,3).join(''); }
const namePatterns = [
  /project[_\s]?name\s*[:\|]?\s*([\w\-]+)/i,
  /nom\s+du\s+projet\s*[:\|]?\s*([\w\-]+)/i,
  /application\s*[:\|]\s*([\w\-]+)/i,
];
for (const p of namePatterns) {
  const m = userRequest.match(p);
  if (m && m[1].trim().length > 1) { projectName = m[1].trim(); break; }
}

// ── 2. Extraire routes explicites ────────────────────────────────
const explicitRoutes = [];
const routeRegex = /(GET|POST|PUT|PATCH|DELETE)\s+(\/[a-zA-Z0-9_\-\/\{\}:]+)/g;
let rm;
while ((rm = routeRegex.exec(userRequest)) !== null) {
  const method = rm[1].toUpperCase();
  const path   = rm[2].split(/[\s,;]/)[0];
  if (!explicitRoutes.find(r => r.method === method && r.path === path)) {
    explicitRoutes.push({ method, path, description: method + ' ' + path });
  }
}

// ── 3. Détecter ressources métier depuis mots-clés ─────────────
const ACTOR_WORDS = ['user','users','client','clients','admin','admins',
  'voyageur','voyageurs','expediteur','expéditeur','expediteurs','expéditeurs',
  'person','member','passenger','habitant','resident','citoyen'];

const RESOURCE_KEYWORDS = [
  {kw:'trajet',      plural:'trajets',       fields:['ville_depart','ville_arrivee','date_vol','kilos_disponibles','prix_par_kilo']},
  {kw:'annonce',     plural:'annonces',       fields:['titre','kilos_disponibles','prix_par_kilo','trajet_id']},
  {kw:'reservation', plural:'reservations',   fields:['trajet_id','poids_kg','statut','expediteur_nom']},
  {kw:'paiement',    plural:'paiements',      fields:['reservation_id','montant','statut','methode']},
  {kw:'evaluation',  plural:'evaluations',    fields:['reservation_id','note','commentaire']},
  {kw:'signalement', plural:'signalements',   fields:['description','latitude','longitude','priorite','statut']},
  {kw:'intervention',plural:'interventions',  fields:['signalement_id','equipe','statut']},
  {kw:'commande',    plural:'commandes',       fields:['produit_id','quantite','statut','montant']},
  {kw:'produit',     plural:'produits',        fields:['nom','prix','stock','description']},
  {kw:'livraison',   plural:'livraisons',      fields:['commande_id','statut','adresse']},
  {kw:'colis',       plural:'colis',           fields:['description','poids_kg','statut','reservation_id']},
  {kw:'tache',       plural:'taches',          fields:['titre','description','statut','priorite']},
  {kw:'article',     plural:'articles',        fields:['titre','contenu','auteur','statut']},
];

let detectedResources = [];

if (explicitRoutes.length >= 3) {
  // Extraire depuis routes explicites
  const segs = new Set();
  explicitRoutes.forEach(r => {
    const seg = r.path.replace(/^\//, '').split('/')[0].replace(/[{:}]/g,'');
    if (seg && seg !== 'health' && !ACTOR_WORDS.includes(seg)) segs.add(seg);
  });
  segs.forEach(seg => {
    // Chercher la config connue
    const known = RESOURCE_KEYWORDS.find(rk => rk.plural === seg || rk.kw === seg || seg.startsWith(rk.kw));
    if (known) {
      detectedResources.push({ name: known.kw, name_plural: known.plural, known_fields: known.fields });
    } else {
      detectedResources.push({ name: seg.replace(/s$/,''), name_plural: seg, known_fields: [] });
    }
  });
} else {
  // Détecter depuis mots-clés dans le texte
  RESOURCE_KEYWORDS.forEach(rk => {
    const regex = new RegExp('\\b(' + rk.kw + '|' + rk.plural + ')\\b', 'gi');
    const matches = userRequest.match(regex);
    if (matches && matches.length >= 3) {
      detectedResources.push({ name: rk.kw, name_plural: rk.plural, known_fields: rk.fields, count: matches.length });
    }
  });
  // Trier par fréquence, garder max 6 (aligné sur le plafond du pipeline)
  detectedResources.sort((a,b) => (b.count||0) - (a.count||0));
  detectedResources = detectedResources.slice(0, 6);
}

// ── 4. Construire resources avec vrais champs ───────────────────
const resources = detectedResources.map(r => {
  const fields = { id: 'number', created_at: 'string' };
  const reqFields = [];

  // Utiliser les champs connus pour cette ressource
  (r.known_fields || []).forEach(f => {
    const ftype = f.endsWith('_id') || f.includes('montant') || f.includes('prix') ||
                  f.includes('poids') || f.includes('note') || f.includes('kilos') ||
                  f.includes('stock') || f.includes('quantite') ? 'number' : 'string';
    fields[f] = ftype;
    reqFields.push(f);
  });

  // Si aucun champ connu, extraire depuis les tables Markdown dans le texte
  if (reqFields.length === 0) {
    const singular = r.name;
    const resIdx = lines.findIndex(l => l.toLowerCase().includes(singular));
    if (resIdx >= 0) {
      const block = lines.slice(Math.max(0, resIdx-2), resIdx+15).join('\n');
      const tableRows = block.match(/\|\s*([a-z_]{2,30})\s*\|\s*(string|number|text|int|float)/gi) || [];
      tableRows.forEach(row => {
        const parts = row.split('|').map(p => p.trim()).filter(Boolean);
        if (parts.length >= 2 && !['id','created_at'].includes(parts[0].toLowerCase())) {
          const fname = parts[0].toLowerCase().replace(/\s+/g,'_');
          const ftype = parts[1].toLowerCase().includes('number') || parts[1].toLowerCase().includes('int') ? 'number' : 'string';
          fields[fname] = ftype;
          reqFields.push(fname);
        }
      });
    }
  }

  // Fallback minimaliste
  if (reqFields.length === 0) {
    fields['titre'] = 'string'; fields['statut'] = 'string';
    reqFields.push('titre', 'statut');
  }

  return { name: r.name, name_plural: r.name_plural, fields, required_fields: reqFields.slice(0,5) };
});

// ── 5. Construire routes ──────────────────────────────────────────
// Plafonnement par ressource (jamais par endpoint brut) : garantit qu'une
// ressource ne perd pas son GET si son POST est apparu avant la coupe.
function capRoutesByResource(routes, maxResources) {
  const resourceOrder = [];
  routes.forEach(r => {
    const seg = r.path.replace(/^\//, '').split('/')[0];
    if (seg && resourceOrder.indexOf(seg) === -1) resourceOrder.push(seg);
  });
  const kept = resourceOrder.slice(0, maxResources);
  return routes.filter(r => kept.indexOf(r.path.replace(/^\//, '').split('/')[0]) !== -1);
}

const finalRoutes = [{ method: 'GET', path: '/health', description: 'health check' }];
if (explicitRoutes.length >= 3) {
  capRoutesByResource(explicitRoutes.filter(r => r.path !== '/health'), 6).forEach(r => finalRoutes.push(r));
} else {
  resources.slice(0,6).forEach(r => {
    finalRoutes.push({ method: 'POST', path: '/' + r.name_plural, description: 'Créer un(e) ' + r.name + ' (champs: ' + r.required_fields.join(', ') + ')' });
    finalRoutes.push({ method: 'GET',  path: '/' + r.name_plural, description: 'Lister tous les ' + r.name_plural });
  });
}

// ── 6. normalized_userRequest ─────────────────────────────────────
let normalizedText = '# ' + projectName + '\n\n';
normalizedText += 'RESSOURCES API :\n';
resources.forEach(r => {
  const fields = Object.keys(r.fields).filter(k => !['id','created_at'].includes(k))
    .map(k => k + ':' + r.fields[k]).join(', ');
  normalizedText += '- ' + r.name_plural + ' (' + fields + ')\n';
  normalizedText += '  Champs requis: ' + r.required_fields.join(', ') + '\n';
});
normalizedText += '\nROUTES :\n';
finalRoutes.forEach(rt => { normalizedText += '- ' + rt.method + ' ' + rt.path + ' : ' + rt.description + '\n'; });

const deterministicContext = JSON.stringify({
  project_name: projectName, resources, routes: finalRoutes, business_rules: [], _source: 'deterministic'
});


// ── display_name : nettoyer les noms parasites (en-têtes de doc PDF) ──────
function cleanDisplayName(rawName) {
  if (!rawName || rawName === 'Application') return rawName || 'Application';
  const INVALID_FIRST_WORDS = ['specifications','specification','document','template',
    'doc','rapport','report','fichier','forge','test','projet','project',
    'plateforme','platform','plateformeweb','application','app','appli','web',
    'site','logiciel','systeme','system','outil','solution','portail'];
  var words = rawName.trim().split(/[\s\-_]+/).filter(function(w){ return w.length > 0; });
  // Retirer successivement TOUS les mots generiques en tete (ex: 'Plateforme web CrimeStopper' -> 'CrimeStopper')
  while (words.length > 1) {
    var fw = (words[0] || '').toLowerCase().replace(/[^a-z]/g,'');
    if (INVALID_FIRST_WORDS.indexOf(fw) !== -1) { words.shift(); } else { break; }
  }
  var cleaned = words.join(' ').trim();
  return cleaned.length > 1 ? cleaned : rawName.trim();
}

// ── markdown_summary : format compact ~400 chars ──────────────────────────
function buildMarkdownSummary(projectName, resources, routes, rules) {
  var md = '# ' + projectName + '\n';
  md += 'REST+Web | Node.js/Express\n';
  if (resources && resources.length > 0) {
    md += '\n## Resources\n';
    resources.forEach(function(r) {
      var flds = Object.keys(r.fields || {}).filter(function(k){ return !['id','created_at'].includes(k); })
        .map(function(k){
          var t = r.fields[k] === 'number' ? 'num' : 'str';
          var req = (r.required_fields || []).includes(k) ? '*' : '';
          var fk  = k.endsWith('_id') ? ',FK' : '';
          return k + req + '(' + t + fk + ')';
        }).join(', ');
      md += '- ' + (r.name_plural || r.name) + ': ' + flds + '\n';
    });
  }
  if (routes && routes.length > 0) {
    md += '\n## Routes\n';
    md += routes.map(function(r){ return r.method + ' ' + r.path; }).join(' | ') + '\n';
  }
  if (rules && rules.length > 0) {
    md += '\n## Rules\n';
    md += rules.slice(0, 5).join(' | ') + '\n';
  }
  return md.substring(0, 800);
}

// ── richness_score : 0-100, évalue la richesse sémantique de la spec ──────
function computeRichnessScore(resources, routes, rules, source) {
  var score = 0;
  var res = resources || [];
  var rts = routes || [];
  var rls = rules || [];
  // 40pts : ressources avec ≥ 3 champs non-système
  var richRes = res.filter(function(r) {
    return Object.keys(r.fields || {}).filter(function(k){ return !['id','created_at'].includes(k); }).length >= 3;
  });
  score += richRes.length > 0 ? 40 : (res.length > 0 ? 20 : 0);
  // 30pts : règles métier
  score += rls.length > 2 ? 30 : (rls.length > 0 ? 15 : 0);
  // 20pts : FK détectées
  var hasFk = res.some(function(r){ return (r.required_fields||[]).some(function(f){ return f.endsWith('_id'); }); });
  score += hasFk ? 20 : 0;
  // 10pts : project_name propre
  score += (source !== 'Application' && source && !source.toLowerCase().includes('specification')) ? 10 : 0;
  return Math.min(100, score);
}

// Construire markdown_summary depuis le contexte déterministe
var _detParsed = {};
try { _detParsed = JSON.parse(deterministicContext); } catch(e) {}
var _displayName     = cleanDisplayName(projectName);
var _markdownSummary = buildMarkdownSummary(_displayName, _detParsed.resources||[], _detParsed.routes||[], _detParsed.business_rules||[]);
var _richnessScore   = computeRichnessScore(_detParsed.resources||[], _detParsed.routes||[], _detParsed.business_rules||[], _displayName);

return [{ json: {
  task_id, userRequest, language, framework,
  project_name:           _displayName,
  display_name:           _displayName,
  deterministic_context:  deterministicContext,
  normalized_userRequest: normalizedText,
  markdown_summary:       _markdownSummary,
  richness_score:         _richnessScore,
  resource_count:         resources.length,
  has_explicit_routes:    explicitRoutes.length >= 3,
  needs_llm:              true
}}];

const inp = $input.first().json;

const systemPrompt = `Tu es un expert en analyse de spécifications logicielles.
RÈGLE ABSOLUE : Retourner UNIQUEMENT un objet JSON valide, aucun texte avant ou après.

FORMAT OBLIGATOIRE :
{
  "project_name": "NomCourt (1-3 mots)",
