    {"method": "GET",  "path": "/health",   "description": "health check"},
    {"method": "POST", "path": "/annonces", "description": "créer une annonce (champs: titre, kilos_disponibles)"},
    {"method": "GET",  "path": "/annonces", "description": "lister toutes les annonces"}
  ],
  "business_rules": ["règle courte 1", "règle courte 2"],
