1. ACTEURS (voyageur, expéditeur, client, admin) ne sont PAS des ressources API
2. RESSOURCES = données échangées (annonces, trajets, reservations, paiements)
3. Maximum 6 ressources. Pour CHAQUE ressource retenue, générer POST + GET
   (jamais l'un sans l'autre). Si plus de 6 ressources métier apparaissent dans
   le texte, ne retenir que les 6 plus centrales au MVP.
4. Types de champs : uniquement "string" ou "number"
5. Champs FK : se terminent par _id (ex: trajet_id, annonce_id)`;

const userPrompt = 'Analyse et normalise cette spec :\n\n' +
  inp.userRequest.substring(0, 5000) +
  '\n\nRetourne UNIQUEMENT le JSON.';

return [{ json: {
  model: 'codestral-latest',
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user',   content: userPrompt }
  ],
  temperature: 0,
  max_tokens: 3500,
  response_format: { type: 'json_object' }
}}];

const inp = $input.first().json;

// Récupérer les données d'entrée depuis Parse Input
let task_id = 'unknown';
let origSpec = '';
let language = 'javascript';
let framework = 'express';
try {
  const pi = $('Parse Input').first().json;
  task_id  = pi.task_id     || 'unknown';
  origSpec = pi.userRequest || '';
  language = pi.language    || 'javascript';
  framework= pi.framework   || 'express';
} catch(e) {}

let parsed = null;
try {
  const content = inp.choices && inp.choices[0] && inp.choices[0].message
    ? inp.choices[0].message.content : null;
  if (!content) throw new Error('Pas de contenu LLM');
  const cleaned = content.replace(/```json\n?/g,'').replace(/```\n?/g,'').trim();
  parsed = JSON.parse(cleaned);
} catch(e) {
  return [{ json: {
    task_id, normalized: false,
    normalized_userRequest: origSpec,
    structured_context: '',
    language, framework,
    _normalization_error: e.message
  }}];
}

const pn       = parsed.project_name || 'Application';
const routes   = Array.isArray(parsed.routes)         ? parsed.routes   : [];
const resources= Array.isArray(parsed.resources)      ? parsed.resources: [];
const rules    = Array.isArray(parsed.business_rules) ? parsed.business_rules : [];

let normalizedText = '# ' + pn + '\n\n';
if (parsed.normalized_spec) {
  normalizedText += parsed.normalized_spec;
} else {
  normalizedText += 'RESSOURCES :\n';
  resources.forEach(function(r) {
    var fields = Object.keys(r.fields || {}).map(function(k){ return k + ':' + r.fields[k]; }).join(', ');
    normalizedText += '- ' + r.name + ' (' + fields + ')\n';
    normalizedText += '  Requis: ' + (r.required_fields || []).join(', ') + '\n';
  });
  normalizedText += '\nROUTES :\n';
  routes.forEach(function(rt) {
    normalizedText += '- ' + rt.method + ' ' + rt.path + ' : ' + rt.description + '\n';
  });
  if (rules.length > 0) {
    normalizedText += '\nRÈGLES :\n';
    rules.forEach(function(rule) { normalizedText += '- ' + rule + '\n'; });
  }
}

const structuredContext = JSON.stringify({
  project_name: pn, resources, routes, business_rules: rules
}, null, 0);


