var _displayName2     = cleanDisplayName(pn);
var _markdownSummary2 = buildMarkdownSummary(_displayName2, resources, routes, rules);
var _richnessScore2   = computeRichnessScore(resources, routes, rules, _displayName2);

return [{ json: {
  task_id,
  normalized:             true,
  project_name:           _displayName2,
  display_name:           _displayName2,
  normalized_userRequest: normalizedText.substring(0, 3000),
  structured_context:     structuredContext.substring(0, 4000),
  markdown_summary:       _markdownSummary2,
  richness_score:         _richnessScore2,
  spec_too_sparse:        _richnessScore2 < 50,
  resources, routes, business_rules: rules,
  language, framework
}}];

// Fallback : Mistral — fallback — utiliser l'extraction déterministe
let task_id = 'unknown';
let origSpec = '';
let language = 'javascript';
let framework = 'express';
let deterministicContext = '';
let projectName = 'Application';

try {
  const pi = $('Parse Input').first().json;
  task_id              = pi.task_id              || 'unknown';
  origSpec             = pi.userRequest          || '';
  language             = pi.language             || 'javascript';
  framework            = pi.framework            || 'express';
  deterministicContext = pi.deterministic_context || '';
  projectName          = pi.project_name          || 'Application';
